   var bad=own.copy();bad.putString("ChairHeight","unknown");var inert=new NativeChairEntity(at,world.getBlockState(at));inert.loadWithComponents(bad,world.registryAccess());need(inert.inert()&&inert.saveWithoutMetadata(world.registryAccess()).equals(bad),"malformed own field inert exact");
